"""End-to-end coverage for workspace 2.1; uses the isolated browser fixture."""
import base64,json
from datetime import date
from playwright.sync_api import expect

def run(page,context,origin,capability,artifacts):
    page.set_viewport_size({'width':1440,'height':1100})
    page.click('[data-page="board"]')
    def quick(title):page.fill('#quickTitle',title);page.press('#quickTitle','Enter');expect(page.locator('.card').filter(has_text=title)).to_have_count(1)
    def card(title):return page.locator('.card').filter(has=page.locator('h3',has_text=title))
    quick('2.1 前置');quick('2.1 交付')
    card('2.1 交付').click();page.select_option('#taskPriority','0');page.check('#taskToday')
    page.click('#dueButton');page.click('[data-offset="0"]')
    page.locator('summary',has_text='重复、依赖与提醒').click()
    page.select_option('#taskRepeat','daily');page.select_option('#taskReminder','today');page.fill('#reminderTime','00:00')
    page.locator('#taskDependencies label').filter(has_text='2.1 前置').locator('input').check()
    page.click('#saveTask');expect(page.locator('#drawer')).to_be_hidden()
    expect(card('2.1 交付').locator('.blocked')).to_contain_text('2.1 前置')
    page.select_option('#priorityFilter','0');expect(page.locator('.card')).to_have_count(1)
    page.click('#saveView');page.fill('#dlg-name','紧急工作');page.press('#dlg-name','Enter');expect(page.locator('[data-view]')).to_have_count(1)
    page.click('#clearFilters');page.click('[data-view]');expect(page.locator('.card')).to_have_count(1)
    page.click('[data-page="today"]');expect(page.locator('#pageContent')).to_contain_text('2.1 交付')
    page.click('[data-page="reminders"]');expect(page.locator('#reminderItems')).to_contain_text('2.1 交付')
    page.click('[data-reminder-snooze]');expect(page.locator('#reminderItems')).not_to_contain_text('2.1 交付')
    page.click('[data-page="board"]');page.click('#clearFilters')
    card('2.1 交付').click();page.select_option('#taskStatus','完成');page.click('#saveTask');expect(page.locator('#toast')).to_contain_text('请先完成依赖')
    page.select_option('#taskStatus','进行中');page.click('#saveTask');expect(page.locator('#drawer')).to_be_hidden()
    card('2.1 前置').click();page.select_option('#taskStatus','完成');page.click('#saveTask');expect(page.locator('#drawer')).to_be_hidden()
    card('2.1 交付').click();page.select_option('#taskStatus','完成');page.click('#saveTask');expect(card('2.1 交付')).to_have_count(2)
    # Undo removes only the requested trash action, then restores the card.
    card('2.1 前置').click();page.click('#trashTask');expect(page.locator('#drawer')).to_be_hidden();page.click('#undoButton');expect(card('2.1 前置')).to_have_count(1)
    page.click('#bulkToggle');card('2.1 前置').locator('[data-select]').check();page.click('#bulkEdit');page.select_option('#dlg-priority','1');page.click('#dialogOk');expect(card('2.1 前置').locator('.priority')).to_have_text('高');page.click('#bulkToggle')
    page.click('[data-page="tags"]');page.select_option('[data-tag-color]','blue');expect(page.locator('.list-row .tag')).to_have_class('tag color-blue')
    page.click('#newTag');page.fill('#dlg-name','待合并');page.press('#dlg-name','Enter');expect(page.locator('[data-tag-merge]')).to_have_count(2)
    page.locator('.list-row').filter(has_text='待合并').locator('[data-tag-merge]').click();page.click('#dialogOk');expect(page.locator('[data-tag-merge]')).to_have_count(1)
    page.click('[data-page="board"]');page.click('#newTask');page.fill('#taskTitle','2.1 草稿和附件');page.fill('#taskNote','恢复后仍需正式保存')
    png=base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jD1cAAAAASUVORK5CYII=')
    page.set_input_files('#fileInput',[{'name':'图片A.png','mimeType':'image/png','buffer':png},{'name':'图片B.png','mimeType':'image/png','buffer':png}])
    page.evaluate("""()=>{const dt=new DataTransfer();dt.items.add(new File(['dragged content'],'拖入文档.txt',{type:'text/plain'}));document.querySelector('#drawer').dispatchEvent(new DragEvent('drop',{bubbles:true,dataTransfer:dt}));}""")
    expect(page.locator('#draftStatus')).to_contain_text('草稿已保存',timeout=15000)
    page.once('dialog',lambda d:d.accept());page.reload();expect(page.locator('#workspace')).to_be_visible()
    page.locator('#draftRecovery summary').click();page.click('[data-recover]');expect(page.locator('#taskTitle')).to_have_value('2.1 草稿和附件');expect(page.locator('#taskNote')).to_have_value('恢复后仍需正式保存');expect(page.locator('[data-remove-new]')).to_have_count(3)
    page.click('#saveTask');expect(page.locator('#drawer')).to_be_hidden();card('2.1 草稿和附件').click();expect(page.locator('[data-preview]')).to_have_count(2)
    page.locator('[data-preview]').first.click();page.click('#nextImage');expect(page.locator('#previewName')).to_contain_text('图片B');page.press('#imageDialog','ArrowLeft');expect(page.locator('#previewName')).to_contain_text('图片A');page.click('#closeImage')
    page.fill('#attachmentSearch','拖入');expect(page.locator('#files .file-row:visible')).to_have_count(1);page.fill('#attachmentSearch','')
    page.screenshot(path=str(artifacts/'workspace-2.1-drawer.png'));page.click('#cancelTask')
    page.evaluate('window.scrollTo(0,0)');page.screenshot(path=str(artifacts/'workspace-2.1-board.png'),full_page=True)
    page.click('[data-page="tools"]');expect(page.locator('#pageContent')).to_contain_text('2.1.0')
    with page.expect_download() as event:page.click('#diagnosticsBtn')
    data=json.loads(open(event.value.path(),encoding='utf-8').read());assert data['version']=='2.1.0' and '2.1 草稿和附件' not in str(data)
    page.select_option('#closeBehavior','tray');page.click('#settingsForm button');expect(page.locator('#toast')).to_have_text('设置已保存')
    assert context.request.get(origin+'/api/state').json()['info']['close_behavior']=='tray'
    print('PASS 2.1 UI: priority/today/views, dependencies/repeat/reminders, undo/bulk/tags, persisted draft/files/drop/search/gallery, diagnostics and close preference')
